const body = $json.body ?? $json;
if (body.eventType !== 'candidate_application_submitted') throw new Error('Invalid candidate application event');
const roleId = String(body.Role_ID ?? body.roleId ?? '').trim();
const candidate = body.candidate ?? {};
const resumeText = String(candidate.resumeText ?? '').trim();
const contactNumber = String(candidate.preferredMobile ?? candidate.phone ?? '').trim();
const applicantCountry = String(candidate.applicantCountry ?? body.applicantCountry ?? '').trim().toUpperCase();
if (!roleId || !String(candidate.name ?? '').trim() || !String(candidate.email ?? '').includes('@') || resumeText.length < 20) throw new Error('Candidate application is incomplete');
if (applicantCountry && !['PH', 'SG', 'MY', 'SA'].includes(applicantCountry)) throw new Error('Unsupported applicant country');
const salaryExpectation = String(candidate.salaryExpectation ?? '').trim();
const salaryCurrency = String(candidate.salaryCurrency ?? '').trim();
const storedSalary = [salaryCurrency, salaryExpectation].filter(Boolean).join(' ');
const approvedSalaryOrBudgetRange = String(body.approvedSalaryOrBudgetRange ?? '').trim();
return [{json:{'Application ID':body.applicationId ?? '', Candidate_Name:candidate.name ?? '', 'Candidate Name':candidate.name ?? '', Email:candidate.email ?? '', Phone:contactNumber, Contact_Number:contactNumber, 'Contact Number':contactNumber, Preferred_Mobile:contactNumber, Applicant_Country:applicantCountry, Role_ID:roleId, 'Selected Role':body.jobTitle ?? body.selectedRole ?? '', Department:body.department ?? '', Resume_Text:resumeText, 'Resume/CV':resumeText, Salary_Expectation:storedSalary, Salary_Currency:salaryCurrency, Approved_Salary_or_Budget_Range:approvedSalaryOrBudgetRange, Salary_Match_Status:'Not evaluated', Salary_Match_Notes:'', Application_Source:body.applicationSource ?? candidate.applicationSource ?? 'Direct Application', 'Status (Resume Processing)':'Submitted', 'Date of Application':body.submittedAt ?? new Date().toISOString(), Resume_File_Id:body.resumeFile?.fileId ?? '', Resume_File_Name:body.resumeFile?.fileName ?? '', Resume_File_Mime_Type:body.resumeFile?.mimeType ?? ''}}];
